package com.zjnu.lab.mapper;
import org.apache.ibatis.annotations.*; import java.util.*;
@Mapper public interface DashboardMapper {
 @Select("<script>select (select count(*) from reservation where 1=1 <if test='labIds!=null'>and lab_id in <foreach collection='labIds' item='id' open='(' separator=',' close=')'>#{id}</foreach></if>) reservations,(select count(*) from reservation where status='PENDING' <if test='labIds!=null'>and lab_id in <foreach collection='labIds' item='id' open='(' separator=',' close=')'>#{id}</foreach></if>) pending,(select count(*) from device where 1=1 <if test='labIds!=null'>and lab_id in <foreach collection='labIds' item='id' open='(' separator=',' close=')'>#{id}</foreach></if>) devices,(select count(*) from device where status='FAULT' <if test='labIds!=null'>and lab_id in <foreach collection='labIds' item='id' open='(' separator=',' close=')'>#{id}</foreach></if>) faults,(select count(*) from repair_order r join device d on d.id=r.device_id where r.status in ('PENDING','PROCESSING') <if test='labIds!=null'>and d.lab_id in <foreach collection='labIds' item='id' open='(' separator=',' close=')'>#{id}</foreach></if>) repairs</script>") Map<String,Object> summary(@Param("labIds")List<Long> labIds);
 @Select("<script>select status name,count(*) amount from reservation where 1=1 <if test='labIds!=null'>and lab_id in <foreach collection='labIds' item='id' open='(' separator=',' close=')'>#{id}</foreach></if> group by status</script>") List<Map<String,Object>> reservationStatus(@Param("labIds")List<Long> labIds);
 @Select("<script>select status name,count(*) amount from device where 1=1 <if test='labIds!=null'>and lab_id in <foreach collection='labIds' item='id' open='(' separator=',' close=')'>#{id}</foreach></if> group by status</script>") List<Map<String,Object>> deviceStatus(@Param("labIds")List<Long> labIds);
}
